import { Handle, Position } from "reactflow";
import { useEffect, useRef } from "react";
import { gsap } from "gsap";

export const BaseNode = ({ title, inputs = [], outputs = [], children }) => {
  const ref = useRef(null);

  useEffect(() => {
    gsap.from(ref.current, {
      scale: 0.9,
      opacity: 0,
      duration: 0.25,
      ease: "power2.out",
    });
  }, []);

  return (
    <div
      ref={ref}
      className="bg-slate-800 text-white rounded-xl shadow-lg border border-slate-700 px-4 py-3 min-w-[180px]"
    >
      <div className="text-sm font-semibold mb-2">{title}</div>

      {inputs.map((id) => (
        <Handle key={id} type="target" position={Position.Left} id={id} />
      ))}

      <div className="text-xs text-slate-300">{children}</div>

      {outputs.map((id) => (
        <Handle key={id} type="source" position={Position.Right} id={id} />
      ))}
    </div>
  );
};
